mapper.select:
SELECT t.id as id, t.code as code, t.shipping as shipping, t.shipping_uscc as shippingUscc, t.shipping_main as shippingMain, t.customer as customer, t.customer_uscc as customerUscc, t.sale_org as saleOrg, t.sale_org_uscc as saleOrgUscc, t.year as year, t.total_volume as totalVolume, t.product_line_id as productLineId, t.product_line_code as productLineCode, t.product_line_name as productLineName, t.effective_date as effectiveDate, t.expiry_date as expiryDate, t.virtual_tag as virtualTag, t.parent_id as parentId, t.num as num, t.remark as remark, t.disabled as disabled, t.busi_source as busiSource, t.system_source as systemSource, t.main_id as mainId, t.create_id as createId, t.create_time as createTime, t.create_name as createName, t.modify_id as modifyId, t.modify_time as modifyTime, t.modify_name as modifyName, t.deleted as deleted FROM frame_agreement t
t.deleted = 0
and t.code = #{queryParam.code}
and t.shipping_uscc = #{queryParam.shippingUscc}
and t.customer_uscc = #{queryParam.customerUscc}
and t.sale_org_uscc = #{queryParam.saleOrgUscc}
and t.product_line_name = #{queryParam.productLineName}
and t.disabled = #{queryParam.disabled}
and t.virtual_tag = #{queryParam.virtualTag}
and t.busi_source in
#{id}
and date_format(t.create_time,'%Y-%m-%d') >= date_format(#{queryParam.startTime},'%Y-%m-%d')
and date_format(t.create_time,'%Y-%m-%d') <= date_format(#{queryParam.endTime},'%Y-%m-%d')
order by t.disabled , t.create_time desc
